fn bracket_depth(s: String) -> Result[Int, String] {
  let mut depth = 0;
  let mut max_depth = 0;
  let mut stack = Vec::new();

  for (i, c) in s.chars().enumerate() {
    match c {
      '(' | '[' | '{' => {
        stack.push(c);
        depth += 1;
        if depth > max_depth {
          max_depth = depth;
        }
      },
      ')' => {
        if stack.pop() != Some('(') {
          return Err(format!("mismatch at {}", i));
        }
        depth -= 1;
      },
      ']' => {
        if stack.pop() != Some('[') {
          return Err(format!("mismatch at {}", i));
        }
        depth -= 1;
      },
      '}' => {
        if stack.pop() != Some('{') {
          return Err(format!("mismatch at {}", i));
        }
        depth -= 1;
      },
      _ => (),
    }
  }

  if !stack.is_empty() {
    return Err("unclosed at end".to_string());
  }

  Ok(max_depth)
}

