fn next_permutation(xs: List[Int]) -> List[Int] {
  let n = len(xs)
  if n <= 1 {
    return xs
  }
  var i = n - 2
  while i >= 0 && xs[i] >= xs[i + 1] {
    i = i - 1
  }
  if i >= 0 {
    var j = n - 1
    while xs[j] <= xs[i] {
      j = j - 1
    }
    xs[i] = xs[j]
    xs = reverse(xs[i + 1..n])
  } else {
    xs = reverse(xs)
  }
  return xs
}

