type Instr =
  | Push(n: Int)
  | Pop
  | Add
  | Sub
  | Mul
  | Dup
  | Swap
  | Jz(target: Int)
  | Jmp(target: Int)
  | Print
  | Halt

fn stack_vm(prog: List[Instr]) -> Result[List[Int], String] {
  effects: io
  requires: len(prog) <= 1000
  ensures: result.is_ok() || result.is_err()
{
  var stack: List[Int] = []
  var ip: Int = 0
  var steps: Int = 0

  while ip < len(prog) && steps < 1000 {
    steps = steps + 1
    let instr = prog[ip]
    match instr {
      Push(n) => stack = append(stack, n),
      Pop => {
        if len(stack) == 0 {
          return Err("stack underflow at " + to_string(ip))
        }
        stack = drop(stack, 1)
      },
      Add => {
        if len(stack) < 2 {
          return Err("stack underflow at " + to_string(ip))
        }
        let b = stack[0]
        let a = stack[1]
        stack = drop(stack, 2)
        stack = append(stack, a + b)
      },
      Sub => {
        if len(stack) < 2 {
          return Err("stack underflow at " + to_string(ip))
        }
        let b = stack[0]
        let a = stack[1]
        stack = drop(stack, 2)
        stack = append(stack, a - b)
      },
      Mul => {
        if len(stack) < 2 {
          return Err("stack underflow at " + to_string(ip))
        }
        let b = stack[0]
        let a = stack[1]
        stack = drop(stack, 2)
        stack = append(stack, a * b)
      },
      Dup => {
        if len(stack) == 0 {
          return Err("stack underflow at " + to_string(ip))
        }
        let a = stack[0]
        stack = append(stack, a)
      },
      Swap => {
        if len(stack) < 2 {
          return Err("stack underflow at " + to_string(ip))
        }
        let b = stack[0]
        let a = stack[1]
        stack = drop(stack, 2)
        stack = append(stack, b)
        stack = append(stack, a)
      },
      Jz(target) => {
        if len(stack) == 0 {
          return Err("stack underflow at " + to_string(ip))
        }
        let a = stack[0]
        stack = drop(stack, 1)
        if a == 0 {
          ip = target
        }
      },
