fn align_columns(rows: List[List[String]]) -> List[String] {
  let max_widths = rows
    |> map(|row| row |> map(|cell| str_len(cell)))
    |> fold(|acc, widths| widths |> zip(acc) |> map(|(w1, w2)| max(w1, w2)))
    |> map(|width| width + 3)  // Add padding for the separator

  return rows
    |> map(|row| {
      row
        |> map(|cell| cell + repeat(" ", max_widths[str_len(cell)] - str_len(cell)))
        |> join(" | ")
        |> trim()
    })
}

