fn count_frequencies(xs: List[Int]) -> Map[Int, Int] {
  xs
    |> fold(Map.empty[Int, Int], |acc, x| map_set(acc, x, map_get(acc, x).map_or(1, |n| n + 1)))
}

fn sort_by_count(m: Map[Int, Int]) -> List[(Int, Int)] {
  m
    |> map_to_list
    |> sort_by(|&(a, _), &(b, _)| b.cmp(&a))
    |> sort_by(|&(_, a), &(_, b)| a.cmp(&b))
}

fn k_most_frequent(xs: List[Int], k: Int) -> List[(Int, Int)] {
  if k <= 0 {
    return []
  }
  let freqs = count_frequencies(xs)
  sort_by_count(freqs)
    |> take(k)
}

