from typing import Callable, Generic, Literal, TypedDict, TypeVar

T = TypeVar("T")

class Ok(TypedDict, Generic[T]):
    ok: Literal[True]
    value: T

class Err(TypedDict):
    ok: Literal[False]
    error: str

class Person(TypedDict):
    name: str
    age: int

def age_histogram(people: list[Person], width: int) -> Ok[list[tuple[str, int]]] | Err:
    if width < 1:
        return Err(ok=False, error="bad width")
    age_counts = {}
    for person in people:
        if person['age'] < 0:
            return Err(ok=False, error=f"negative age: {person['name']}")
        bucket = (person['age'] // width) * width
        age_counts[bucket] = age_counts.get(bucket, 0) + 1
    return Ok(ok=True, value=[(f"{bucket}-{bucket + width - 1}", count) for bucket, count in sorted(age_counts.items())])

