fn tennis_score(points: String) -> String {
  let mut score = Score {
    love: 0,
    fifteen: 0,
    thirty: 0,
    forty: 0,
    advantage: None,
    game: None,
  };
  for point in points.chars() {
    let point_str = point.to_string();
    match parse_point(point_str) {
      Some(p) => {
        score = update_score(score, p);
        score = determine_score(score);
      },
      None => {
        return "error: bad point";
      },
    }
  }
