    qty: int

class Txn(TypedDict):
    sku: str
    delta: int

def inventory_ledger(stock: list[Stock], txns: list[Txn]) -> Ok[list[Stock]] | Err:
    stock_map = {s['sku']: s for s in stock}
    for i, txn in enumerate(txns, start=1):
        if txn['sku'] not in stock_map:
            return Err(ok=False, error=f"txn {i}: unknown sku {txn['sku']}")
        new_qty = stock_map[txn['sku']]['qty'] + txn['delta']
        if new_qty < 0:
            return Err(ok=False, error=f"txn {i}: {txn['sku']} would go negative")
        stock_map[txn['sku']]['qty'] = new_qty
    return Ok(ok=True, value=sorted(stock_map.values(), key=lambda s: s['sku']))

