export function align_columns(rows: string[][]): string[] {
    const columnWidths = new Array<number>();

    // Determine the maximum width for each column
    rows.forEach(row => {
        row.forEach((cell, index) => {
            if (columnWidths[index] === undefined || cell.length > columnWidths[index]) {
                columnWidths[index] = cell.length;
            }
        });
    });

    // Format each row
    return rows.map(row => {
        return row.map(cell => cell.padEnd(columnWidths[row.indexOf(cell)], ' ')).join(' | ').trimEnd();
    });
}

