class Student(TypedDict):
    name: str
    scores: list[int]

def student_medians(students: list[Student]) -> list[tuple[str, float]]:
    def median(scores: list[int]) -> float:
        sorted_scores = sorted(scores)
        n = len(sorted_scores)
        mid = n // 2
        if n % 2 == 0:
            return (sorted_scores[mid - 1] + sorted_scores[mid]) / 2
        else:
            return sorted_scores[mid]

    return sorted(
        (student['name'], median(student['scores']))
        for student in students
        if student['scores']
    ), key=lambda x: (-x[1], x[0]))

