function bowling_score(rolls: number[]): Result<number> {
    if (rolls.some(r => r < 0 || r > 10)) return { ok: false, error: "invalid roll" };
    let score = 0, i = 0;
    for (let frame = 0; frame < 10; frame++) {
        if (i >= rolls.length) return { ok: false, error: "incomplete game" };
        if (rolls[i] === 10) { // Strike
            score += 10 + rolls[i + 1] + rolls[i + 2];
            i++;
        } else {
            if (rolls[i] + rolls[i + 1] > 10) return { ok: false, error: `too many pins in frame ${frame + 1}` };
            score += rolls[i] + rolls[i + 1];
            i += 2;
        }
    }
    if (i < rolls.length) return { ok: false, error: "too many rolls" };
    return { ok: true, value: score };
}

