function parse_version(version: string): Result<number[]> {
    const parts = version.split('.');
    const parsedParts: number[] = [];
    for (const part of parts) {
        const num = parseInt(part, 10);
        if (isNaN(num)) {
            return { ok: false, error: `bad version: ${version}` };
        }
        parsedParts.push(num);
    }
    return { ok: true, value: parsedParts };
}

export function compare_versions(a: string, b: string): Result<number> {
    const parsedA = parse_version(a);
    if (!parsedA.ok) return parsedA;

    const parsedB = parse_version(b);
    if (!parsedB.ok) return parsedB;

    const maxLen = Math.max(parsedA.value.length, parsedB.value.length);
    for (let i = 0; i < maxLen; i++) {
        const partA = i < parsedA.value.length ? parsedA.value[i] : 0;
        const partB = i < parsedB.value.length ? parsedB.value[i] : 0;
        if (partA < partB) return { ok: true, value: -1 };
        if (partA > partB) return { ok: true, value: 1 };
    }
    return { ok: true, value: 0 };
}

