            return { ok: false, error: `duplicate job: ${job.name}` };
        }
        jobMap.set(job.name, job);
        dependencyCount.set(job.name, job.deps.length);
    }

    // Initialize the queue with jobs that have no dependencies
    const queue: string[] = [];
    for (const [name, count] of dependencyCount) {
        if (count === 0) {
            queue.push(name);
        }
    }

    while (queue.length > 0) {
        const current = queue.shift()!;
        result.push(current);
        for (const dep of jobMap.get(current)!.deps) {
            const count = dependencyCount.get(dep)! - 1;
            dependencyCount.set(dep, count);
            if (count === 0) {
                queue.push(dep);
            }
        }
    }

    // Check for cycles
    if (result.length !== jobs.length) {
        return { ok: false, error: "cycle detected" };
    }

    return { ok: true, value: result };
}

