        if (r < 0 || r >= rows || c < 0 || c >= cols || grid[r][c] !== '#') return;
        grid[r] = grid[r].substring(0, c) + '.' + grid[r].substring(c + 1);
        visit(r - 1, c);
        visit(r + 1, c);
        visit(r, c - 1);
        visit(r, c + 1);
