class Dup(TypedDict):
    kind: Literal["Dup"]

class Swap(TypedDict):
    kind: Literal["Swap"]

class Jz(TypedDict):
    kind: Literal["Jz"]
    target: int

class Jmp(TypedDict):
    kind: Literal["Jmp"]
    target: int

class Print(TypedDict):
    kind: Literal["Print"]

class Halt(TypedDict):
    kind: Literal["Halt"]

Instr = Push | Pop | Add | Sub | Mul | Dup | Swap | Jz | Jmp | Print | Halt

def stack_vm(prog: list[Instr]) -> Ok[list[int]] | Err:
    stack: list[int] = []
    output: list[int] = []
    pc: int = 0
    steps: int = 0
    max_steps: int = 1000

    while pc < len(prog):
        if steps >= max_steps:
            return Err({"ok": False, "error": "step limit exceeded"})
        steps += 1

        instr = prog[pc]
        match instr:
            case Push(n):
                stack.append(n)
            case Pop():
                if not stack:
                    return Err({"ok": False, "error": f"stack underflow at {pc}"})
                stack.pop()
            case Add():
                if len(stack) < 2:
                    return Err({"ok": False, "error": f"stack underflow at {pc}"})
                stack.append(stack.pop() + stack.pop())
            case Sub():
                if len(stack) < 2:
                    return Err({"ok": False, "error": f"stack underflow at {pc}"})
                b, a = stack.pop(), stack.pop()
                stack.append(a - b)
            case Mul():
                if len(stack) < 2:
                    return Err({"ok": False, "error": f"stack underflow at {pc}"})
                stack.append(stack.pop() * stack.pop())
            case Dup():
                if not stack:
                    return Err({"ok": False, "error": f"stack underflow at {pc}"})
                stack.append(stack[-1])
            case Swap():
                if len(stack) < 2:
                    return Err({"ok": False, "error": f"stack underflow at {pc}"})
                stack[-1], stack[-2] = stack[-2], stack[-1]
            case Jz(target):
                if not stack:
                    return Err({"ok": False, "error": f"stack underflow at {pc}"})
                if stack.pop() == 0:
                    pc = target
                    continue
            case Jmp(target):
                if target < 0 or target >= len(prog):
                    return Err({"ok": False, "error": f"bad jump at {pc}"})
                pc = target
                continue
            case Print():
                if not stack:
                    return Err({"ok": False, "error": f"stack underflow at {pc}"})
                output.append(stack.pop())
            case Halt():
                break
        pc += 1

    return Ok({"ok": True, "value": output})

