type Request = { endpoint: string; ms: number; status: number };

export function latency_report(entries: Request[]): [string, number, number, number][] {
    const grouped: { [key: string]: Request[] } = {};
    for (const entry of entries) {
        if (!grouped[entry.endpoint]) {
            grouped[entry.endpoint] = [];
        }
        grouped[entry.endpoint].push(entry);
    }

    const result: [string, number, number, number][] = [];
    for (const endpoint in grouped) {
        const requests = grouped[endpoint];
        const count = requests.length;
        const errors = requests.filter(req => req.status >= 500).length;
        const sortedMs = requests.map(req => req.ms).sort((a, b) => a - b);
        const p90Index = Math.floor((9 * count + 9) / 10) - 1;
        const p90 = sortedMs[p90Index];
        result.push([endpoint, count, p90, errors]);
    }

    return result;
}

