type Line = { sku: string; qty: number; unit_cents: number };
type Result<T> = { ok: true; value: T } | { ok: false; error: string };

function invoice_total(lines: Line[], coupon: string): Result<number> {
  // Step 1: Check for bad quantities
  for (const line of lines) {
    if (line.qty < 1) {
      return { ok: false, error: `bad quantity: ${line.sku}` };
    }
  }

  // Step 2: Calculate line amounts and apply bulk discounts
  let subtotal = 0;
  for (const line of lines) {
    let amount = line.qty * line.unit_cents;
    if (line.qty >= 10) {
      amount -= Math.floor(amount / 10);
    }
    subtotal += amount;
  }

  // Step 3: Apply coupon
  let discount = 0;
  switch (coupon) {
    case "":
      break;
    case "SAVE500":
      discount = 500;
      break;
    case "PCT10":
      discount = Math.floor(subtotal / 10);
      break;
    case "BIG20":
      if (subtotal >= 10000) {
        discount = Math.floor(subtotal / 5);
      } else {
        return { ok: false, error: "coupon not applicable: BIG20" };
      }
      break;
    default:
      return { ok: false, error: `unknown coupon: ${coupon}` };
  }
  subtotal -= discount;

  // Step 4: Calculate tax and total
  const tax = Math.floor((subtotal * 8 + 50) / 100);
  const total = subtotal + tax;

  return { ok: true, value: total };
}

