        const digitsPhone = contact.phone.replace(/\D/g, '');

        if (trimmedEmail) {
            const linkedEmail = emailMap.get(trimmedEmail);
            if (linkedEmail && linkedEmail !== contact.email) {
                contactMap.get(linkedEmail)!.name = contact.name || contactMap.get(linkedEmail)!.name;
                contactMap.get(linkedEmail)!.email = contact.email || contactMap.get(linkedEmail)!.email;
