type ParseResult = { kind: 'error', error: string } | { kind: 'value', value: number, index: number };

function parse_expr(s: string, index: number): ParseResult {
    const termResult = parse_term(s, index);
    if (termResult.kind === 'error') return termResult;
    return parse_binop(s, termResult.value, termResult.index, ['+', '-']);
}

function parse_term(s: string, index: number): ParseResult {
    const factorResult = parse_factor(s, index);
    if (factorResult.kind === 'error') return factorResult;
    return parse_binop(s, factorResult.value, factorResult.index, ['*', '/']);
}

function parse_binop(s: string, left: number, index: number, ops: string[]): ParseResult {
    for (const op of ops) {
        if (s[index] === op) {
            const rightResult = parse_term(s, index + 1);
            if (rightResult.kind === 'error') return rightResult;
            if (op === '/' && rightResult.value === 0) return { kind: 'error', error: 'division by zero' };
            left = op === '+' ? left + rightResult.value : left - rightResult.value;
            index = rightResult.index;
        }
    }
    return { kind: 'value', value: left, index };
}

