    if (s[index] === '(') {
        const exprResult = parse_expr(s, index + 1);
        if (exprResult.kind === 'error') return exprResult;
        if (s[exprResult.index] !== ')') return { kind: 'error', error: 'unexpected end' };
        return exprResult;
    }
    const match = s.slice(index).match(/^\d+/);
    if (!match) return { kind: 'error', error: `unexpected character: ${s[index]}` };
    return { kind: 'value', value: parseInt(match[0], 10), index: index + match[0].length };
}

