type Result<T> = { ok: true; value: T } | { ok: false; error: string };

function flatten_nested(s: string): Result<[number[], number]> {
    s = s.replace(/\s/g, '');
    const result: number[] = [];
    let depth = 0, maxDepth = 0;

    function parseElement(i: number): number {
        if (s[i] === '[') {
            depth++;
            maxDepth = Math.max(maxDepth, depth);
            const [value, newIndex] = parseList(i + 1);
            result.push(value);
            return newIndex;
        } else if (s[i] === '-') {
            const [value, newIndex] = parseNumber(i + 1);
            result.push(value);
            return newIndex;
        } else if (s[i] >= '0' && s[i] <= '9') {
            const [value, newIndex] = parseNumber(i);
            result.push(value);
            return newIndex;
        } else {
            throw new Error(`invalid at ${i}`);
        }
    }

    function parseList(i: number): [number[], number] {
        if (s[i] !== '[') throw new Error(`invalid at ${i}`);
        i++;
        const elements: number[] = [];
        while (s[i] !== ']') {
            if (s[i] === ',') {
                i++;
            } else {
                const [value, newIndex] = parseElement(i);
                elements.push(value);
                i = newIndex;
            }
        }
        return [elements, i + 1];
    }

    function parseNumber(i: number): [number, number] {
        let negative = false;
        if (s[i] === '-') {
            negative = true;
            i++;
        }
        if (s[i] < '0' || s[i] > '9') throw new Error(`invalid at ${i}`);
        let value = 0;
        while (i < s.length && s[i] >= '0' && s[i] <= '9') {
            value = value * 10 + (s[i] - '0');
            i++;
        }
        return [negative ? -value : value, i];
    }

    try {
        parseList(0);
        return { ok: true, value: [result, maxDepth] };
    } catch (e) {
        return { ok: false, error: e.message };
    }
}

