type Setting = { section: string; key: string; value: string };
type Result<T> = { ok: true; value: T } | { ok: false; error: string };

function parse_config(lines: string[]): Result<Setting[]> {
    const settings: Setting[] = [];
    let currentSection = "";

    for (let i = 0; i < lines.length; i++) {
        let line = lines[i].trim();
        if (line === "" || line.startsWith("#")) continue;

        if (line.startsWith("[")) {
            const match = line.match(/^\[(.*?)\]$/);
            if (!match || match[1].trim() === "") {
                return { ok: false, error: `line ${i + 1}: bad header` };
            }
            currentSection = match[1].trim();
        } else {
            const match = line.match(/^([^=]+)=(.*)$/);
            if (!match || match[1].trim() === "") {
                return { ok: false, error: `line ${i + 1}: missing = or empty key` };
            }
            const key = match[1].trim();
            const value = match[2].trim();
            settings.push({ section: currentSection, key, value });
        }
    }

    return { ok: true, value: settings };
}

