type Result<T> = { ok: true; value: T } | { ok: false; error: string };

function parse_csv_line(s: string): Result<string[]> {
    const result: string[] = [];
    let i = 0;
    while (i < s.length) {
        if (s[i] === '"') {
            i++;
            let value = '';
            while (i < s.length && s[i] !== '"') {
                if (s[i] === '\\') {
                    i++;
                    if (i < s.length) {
                        value += s[i];
                    } else {
                        return { ok: false, error: 'unterminated quote' };
                    }
                } else {
                    value += s[i];
                }
                i++;
            }
            if (i === s.length) {
                return { ok: false, error: 'unterminated quote' };
            }
            i++;
            result.push(value);
        } else {
            let value = '';
            while (i < s.length && s[i] !== ',') {
                value += s[i];
                i++;
            }
            result.push(value);
        }
        if (i < s.length && s[i] === ',') {
            i++;
        }
    }
    return { ok: true, value: result };
}

