type Result<T> = { ok: true; value: T } | { ok: false; error: string };

function parse_ipv4(s: string): Result<number> {
    const parts = s.split('.');
    if (parts.length !== 4) {
        return { ok: false, error: 'expected 4 parts' };
    }
    for (const part of parts) {
        if (!/^[0-9]{1,3}$/.test(part)) {
            return { ok: false, error: `bad part: ${part}` };
        }
        const num = parseInt(part, 10);
        if (num < 0 || num > 255) {
            return { ok: false, error: `bad part: ${part}` };
        }
    }
    const [a, b, c, d] = parts.map(part => parseInt(part, 10));
    return { ok: true, value: a * 16777216 + b * 65536 + c * 256 + d };
}

