type Result<T> = { ok: true; value: T } | { ok: false; error: string };

function parse_money(s: string): Result<number> {
    if (s.startsWith('-')) {
        s = s.slice(1);
    }
    if (!s.startsWith('$')) {
        return { ok: false, error: 'missing $' };
    }
    s = s.slice(1);
    const parts = s.split('.');
    if (parts.length > 2) {
        return { ok: false, error: 'bad cents' };
    }
    const dollars = parts[0];
    const cents = parts.length === 2 ? parts[1] : '00';
    if (cents.length !== 2 || !/^\d{2}$/.test(cents)) {
        return { ok: false, error: 'bad cents' };
    }
    if (!/^\d+$/.test(dollars)) {
        return { ok: false, error: 'bad dollars' };
    }
    if (dollars.startsWith('0') && dollars !== '0') {
        return { ok: false, error: 'bad dollars' };
    }
    const dollarValue = parseInt(dollars.replace(/,/g, ''), 10);
    const centValue = parseInt(cents, 10);
    const value = dollarValue * 100 + centValue;
    return { ok: true, value: s.startsWith('-') ? -value : value };
}

