type Employee = { name: string; dept: string; hours: number; rate_cents: number };

function payroll_by_dept(emps: Employee[]): ([string, number])[] {
    const deptPays = new Map<string, number>();

    for (const emp of emps) {
        const basePay = Math.min(emp.hours, 40) * emp.rate_cents;
        const overtimePay = Math.max(emp.hours - 40, 0) * emp.rate_cents * 3 / 2;
        const totalPay = Math.floor(basePay + overtimePay);
        deptPays.set(emp.dept, (deptPays.get(emp.dept) || 0) + totalPay);
    }

    return Array.from(deptPays.entries())
        .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]));
}

