function pig_latin(s: string): string {
    return s.split(' ').map(word => translateWord(word)).join(' ');
}

function translateWord(word: string): string {
    const vowels = 'aeiou';
    let firstVowelIndex = -1;

    for (let i = 0; i < word.length; i++) {
        if (vowels.includes(word[i]) && !(word[i] === 'u' && word[i - 1] === 'q')) {
            firstVowelIndex = i;
            break;
        }
    }

    if (firstVowelIndex === -1) {
        return word + 'ay';
    } else if (firstVowelIndex === 0) {
        return word + 'way';
    } else {
        return word.substring(firstVowelIndex) + word.substring(0, firstVowelIndex) + 'ay';
    }
}

