function poker_hand(cards: string[]): string {
    const ranks = "23456789TJQKA";
    const suits = "CDHS";

    // Validate input
    if (cards.length !== 5 || new Set(cards).size !== 5) return "invalid";
    if (!cards.every(card => ranks.includes(card[0]) && suits.includes(card[1]))) return "invalid";

    // Helper functions
    const rankValue = (rank: string) => ranks.indexOf(rank);
    const isFlush = () => cards.every(card => card[1] === cards[0][1]);
    const isStraight = () => {
        const values = cards.map(card => rankValue(card[0]));
        values.sort((a, b) => a - b);
        for (let i = 0; i < 4; i++) {
            if (values[i] + 1 !== values[i + 1]) return false;
        }
        return true;
    };
    const countRanks = () => {
        const counts: { [key: string]: number } = {};
        cards.forEach(card => counts[card[0]] = (counts[card[0]] || 0) + 1);
        return counts;
    };

    // Check hand categories
    if (isFlush() && isStraight()) return "straight flush";
    const counts = countRanks();
    if (Object.values(counts).includes(4)) return "four of a kind";
    if (Object.values(counts).includes(3) && Object.values(counts).includes(2)) return "full house";
    if (isFlush()) return "flush";
    if (isStraight()) return "straight";
    if (Object.values(counts).includes(3)) return "three of a kind";
    if (Object.values(counts).filter(count => count === 2).length === 2) return "two pair";
    if (Object.values(counts).includes(2)) return "one pair";
    return "high card";
}

