type Result<T> = { ok: true; value: T } | { ok: false; error: string };

function parse_duration(s: string): Result<number> {
    if (s === "") return { ok: false, error: "empty" };

    let hours = 0, minutes = 0, seconds = 0;
    let i = 0;

    while (i < s.length) {
        let num = 0;
        while (i < s.length && s[i] >= '0' && s[i] <= '9') {
            num = num * 10 + (s[i] - '0');
            i++;
        }

        if (i === s.length) return { ok: false, error: "missing unit" };

        let unit = s[i];
        i++;

        if (unit === 'h') {
            if (hours > 0) return { ok: false, error: "unit out of order: h" };
            hours = num;
        } else if (unit === 'm') {
            if (minutes > 0) return { ok: false, error: "unit out of order: m" };
            minutes = num;
        } else if (unit === 's') {
            if (seconds > 0) return { ok: false, error: "unit out of order: s" };
            seconds = num;
        } else {
            return { ok: false, error: `unknown unit: ${unit}` };
        }
    }

    return { ok: true, value: hours * 3600 + minutes * 60 + seconds };
}

