function tic_tac_toe(board: string[]): string {
    const rows = board;
    const cols = board.map(row => row[0] + row[1] + row[2]);
    const diags = [board[0][0] + board[1][1] + board[2][2], board[0][2] + board[1][1] + board[2][0]];
    const lines = [...rows, ...cols, ...diags];

    const count = (char: string) => lines.join('').split('').filter(c => c === char).length;
    const xCount = count('X');
    const oCount = count('O');

    if (Math.abs(xCount - oCount) > 1 || (xCount < oCount && xCount !== oCount)) return "invalid";

    const hasLine = (player: string) => lines.some(line => line === player.repeat(3));
    if (hasLine('X') && xCount !== oCount + 1) return "invalid";
    if (hasLine('O') && xCount !== oCount) return "invalid";

    if (hasLine('X')) return "X wins";
    if (hasLine('O')) return "O wins";
    if (xCount + oCount === 9) return "draw";
    return "in progress";
}

