type Sale = { region: string; product: string; units: number; price_cents: number };

export function top_product_per_region(sales: Sale[]): ([string, string, number])[] {
    const revenueMap = new Map<string, Map<string, number>>();

    for (const sale of sales) {
        const { region, product, units, price_cents } = sale;
        const revenue = units * price_cents;
        if (!revenueMap.has(region)) {
            revenueMap.set(region, new Map());
        }
        const productRevenue = revenueMap.get(region)!.get(product) || 0;
        revenueMap.get(region)!.set(product, productRevenue + revenue);
    }

    const result: [string, string, number][] = [];
    for (const [region, productMap] of revenueMap) {
        let topProduct: [string, number] | null = null;
        for (const [product, revenue] of productMap) {
            if (!topProduct || revenue > topProduct[1] || (revenue === topProduct[1] && product < topProduct[0])) {
                topProduct = [product, revenue];
            }
        }
        if (topProduct) {
            result.push([region, topProduct[0], topProduct[1]]);
        }
    }

    return result.sort((a, b) => a[0].localeCompare(b[0]));
}

