                } else {
                    messages.push(`insufficient ${credit}`);
                }
                break;
            case "Refund":
                if (credit > 0) {
                    messages.push(`refund ${credit}`);
                    credit = 0;
                }
                break;
        }
    }

    if (credit > 0) {
        messages.push(`refund ${credit}`);
    }

    return messages;
}

