fn parse_version(version: String) -> Result[List[Int], String] {
  let parts = split(version, ".");
  if len(parts) > 4 {
    return Err("bad version: " + version);
  }
  let parsed_parts = map(parts, |part| {
    let num = parse_int(part);
    if num.is_none() {
      return Err("bad version: " + version);
    }
    return Ok(num.unwrap());
  });
  if contains(parsed_parts, Err(_)) {
    return Err("bad version: " + version);
  }
  return Ok(map_from(parsed_parts, |x| x.unwrap()));
}

