fn next_permutation(xs: List[Int]) -> List[Int] {
  let n = len(xs)
  if n <= 1 {
    return xs
  }
  var i = n - 2
  while i >= 0 && xs[i] >= xs[i + 1] {
    i = i - 1
  }
  if i >= 0 {
    var j = n - 1
    while xs[j] <= xs[i] {
      j = j - 1
    }
    xs = swap(xs, i, j)
  }
  xs = reverse(xs, i + 1, n - 1)
  return xs
}

fn swap(xs: List[Int], i: Int, j: Int) -> List[Int] {
  let temp = xs[i]
  xs[i] = xs[j]
  xs[j] = temp
  return xs
}

fn reverse(xs: List[Int], start: Int, end: Int) -> List[Int] {
  let mut i = start
  let mut j = end
  while i < j {
    xs = swap(xs, i, j)
    i = i + 1
    j = j - 1
  }
  return xs
}

