fn turn(direction: String, cmd: Cmd) -> String {
  match direction {
    "N" => match cmd {
      TurnLeft => "W",
      TurnRight => "E",
      _ => direction,
    },
    "E" => match cmd {
      TurnLeft => "N",
      TurnRight => "S",
      _ => direction,
    },
    "S" => match cmd {
      TurnLeft => "E",
      TurnRight => "W",
      _ => direction,
    },
    "W" => match cmd {
      TurnLeft => "S",
      TurnRight => "N",
      _ => direction,
    },
    _ => direction,
  }
}

fn move(x: Int, y: Int, direction: String, cmd: Cmd) -> (Int, Int) {
  match cmd {
    Forward(steps) => {
      let (dx, dy) = match direction {
        "N" => (0, 1),
        "E" => (1, 0),
        "S" => (0, -1),
        "W" => (-1, 0),
        _ => (0, 0),
      };
      let mut nx = x;
      let mut ny = y;
      for _ in 0..steps {
        nx += dx;
        ny += dy;
        if contains(obstacles, (nx, ny)) {
          break;
        }
      }
      (nx, ny)
    },
    _ => (x, y),
  }
}

