type Rank = "2" | "3" | "4" | "5" | "6" | "7" | "8" | "9" | "T" | "J" | "Q" | "K" | "A";
type Suit = "C" | "D" | "H" | "S";
type Card = (Rank, Suit);
type HandCategory = "straight flush" | "four of a kind" | "full house" | "flush" | "straight" | "three of a kind" | "two pair" | "one pair" | "high card";

fn poker_hand(cards: List[Card]) -> String {
  if cards.len() != 5 {
    return "invalid";
  }
  if !is_unique(cards) {
    return "invalid";
  }
  if is_straight_flush(cards) {
    return "straight flush";
  }
  if let Some(_) = is_four_of_a_kind(cards) {
    return "four of a kind";
  }
  if let Some(_) = is_full_house(cards) {
    return "full house";
  }
  if is_flush(cards) {
    return "flush";
  }
  if is_straight(cards) {
    return "straight";
  }
  if let Some(_) = is_three_of_a_kind(cards) {
    return "three of a kind";
  }
  if let Some(_) = is_two_pair(cards) {
    return "two pair";
  }
  if let Some(_) = is_one_pair(cards) {
    return "one pair";
  }
  return "high card";
}

fn is_unique(cards: List[Card]) -> Bool {
  let mut seen = Map[String, Int]{};
  for (rank, _) in cards {
    let key = to_string(rank);
    if map_get(seen, key).is_some() {
      return false;
    }
    map_set(seen, key, 1);
  }
  return true;
}

fn is_straight_flush(cards: List[Card]) -> Bool {
  return is_flush(cards) && is_straight(cards);
}

fn is_four_of_a_kind(cards: List[Card]) -> Option[Rank] {
  let mut counts = Map[String, Int]{};
  for (rank, _) in cards {
    let key = to_string(rank);
    let count = map_get(counts, key).unwrap_or(0) + 1;
    map_set(counts, key, count);
    if count == 4 {
      return Some(rank);
    }
  }
  return None;
}

fn is_full_house(cards: List[Card]) -> Option<(Rank, Rank)> {
  let mut counts = Map[String, Int]{};
  for (rank, _) in cards {
    let key = to_string(rank);
    let count = map_get(counts, key).unwrap_or(0) + 1;
    map_set(counts, key, count);
  }
