from typing import Callable, Generic, Literal, TypedDict, TypeVar

class Player(TypedDict):
    name: str
    score: int

def competition_rank(players: list[Player]) -> list[tuple[int, str]]:
    ranked = sorted(players, key=lambda p: (-p['score'], p['name']))
    ranks = {}
    rank = 1
    for i, player in enumerate(ranked):
        if i > 0 and player['score'] != ranked[i - 1]['score']:
            rank = i + 1
        ranks[player['name']] = rank
    return [(ranks[player['name']], player['name']) for player in players]

