    while s and s[0] in "*/":
        op, s = s[0], s[1:]
        next_result, s = parse_factor(s)
        if op == "*":
            result *= next_result
        else:
            if next_result == 0:
                raise SyntaxError("division by zero")
            result //= next_result
    return result

