type Result<T> = { ok: true; value: T } | { ok: false; error: string };

export function bracket_depth(s: string): Result<number> {
    const stack: string[] = [];
    let maxDepth = 0;
    let currentDepth = 0;

    for (let i = 0; i < s.length; i++) {
        const char = s[i];
        if (char === '(' || char === '[' || char === '{') {
            stack.push(char);
            currentDepth++;
            maxDepth = Math.max(maxDepth, currentDepth);
        } else if (char === ')' || char === ']' || char === '}') {
            if (stack.length === 0) {
                return { ok: false, error: `mismatch at ${i}` };
            }
            const last = stack.pop()!;
            if (
                (char === ')' && last !== '(') ||
                (char === ']' && last !== '[') ||
                (char === '}' && last !== '{')
            ) {
                return { ok: false, error: `mismatch at ${i}` };
            }
            currentDepth--;
        }
    }

    if (stack.length > 0) {
        return { ok: false, error: 'unclosed at end' };
    }

    return { ok: true, value: maxDepth };
}

