export function caesar_shift(s: string, k: number): string {
    return s.split('').map(c => {
        if (c >= 'a' && c <= 'z') {
            return String.fromCharCode((c.charCodeAt(0) - 'a'.charCodeAt(0) + k + 26) % 26 + 'a'.charCodeAt(0));
        } else {
            return c;
        }
    }).join('');
}

