    const parsedA = parseVersion(a);
    const parsedB = parseVersion(b);

    for (let i = 0; i < 4; i++) {
        if (parsedA[i] < parsedB[i]) return { ok: true, value: -1 };
        if (parsedA[i] > parsedB[i]) return { ok: true, value: 1 };
    }

    return { ok: true, value: 0 };
}

