  const accounts: { [name: string]: number } = {};

  for (let i = 0; i < ops.length; i++) {
    const op = ops[i];
    switch (op.kind) {
      case "Open":
        if (accounts[op.name] !== undefined) {
          return { ok: false, error: `step ${i + 1}: duplicate account ${op.name}` };
        }
        accounts[op.name] = 0;
        break;
      case "Deposit":
        if (accounts[op.name] === undefined) {
          return { ok: false, error: `step ${i + 1}: unknown account ${op.name}` };
        }
        if (op.amount <= 0) {
          return { ok: false, error: `step ${i + 1}: invalid amount` };
        }
        accounts[op.name] += op.amount;
        break;
      case "Withdraw":
        if (accounts[op.name] === undefined) {
          return { ok: false, error: `step ${i + 1}: unknown account ${op.name}` };
        }
        if (op.amount <= 0) {
          return { ok: false, error: `step ${i + 1}: invalid amount` };
        }
        if (accounts[op.name] < op.amount) {
          return { ok: false, error: `step ${i + 1}: insufficient funds` };
        }
        accounts[op.name] -= op.amount;
        break;
      case "Transfer":
        if (accounts[op.src] === undefined) {
          return { ok: false, error: `step ${i + 1}: unknown account ${op.src}` };
        }
        if (accounts[op.dst] === undefined) {
          return { ok: false, error: `step ${i + 1}: unknown account ${op.dst}` };
        }
        if (op.src === op.dst) {
          return { ok: false, error: `step ${i + 1}: same account` };
        }
        if (op.amount <= 0) {
          return { ok: false, error: `step ${i + 1}: invalid amount` };
        }
        if (accounts[op.src] < op.amount) {
          return { ok: false, error: `step ${i + 1}: insufficient funds` };
        }
        accounts[op.src] -= op.amount;
        accounts[op.dst] += op.amount;
        break;
    }
  }

  return { ok: true, value: Object.entries(accounts) };
}

