function count_islands(grid: string[]): [number, number] {
    if (grid.length === 0 || grid[0].length === 0) return [0, 0];

    const rows = grid.length;
    const cols = grid[0].length;
    let islandCount = 0;
    let maxIslandSize = 0;

    const visit = (r: number, c: number): void => {
        if (r < 0 || r >= rows || c < 0 || c >= cols || grid[r][c] !== '#') return;
        grid[r] = grid[r].substring(0, c) + '.' + grid[r].substring(c + 1);
        visit(r - 1, c);
        visit(r + 1, c);
        visit(r, c - 1);
        visit(r, c + 1);
    };

    for (let r = 0; r < rows; r++) {
        for (let c = 0; c < cols; c++) {
            if (grid[r][c] === '#') {
                islandCount++;
                visit(r, c);
                maxIslandSize = Math.max(maxIslandSize, rows * cols - grid.join('').replace(/\./g, '').length);
            }
        }
    }

    return [islandCount, maxIslandSize];
}

