T = TypeVar("T")

class Ok(TypedDict, Generic[T]):
    ok: Literal[True]
    value: T

class Err(TypedDict):
    ok: Literal[False]
    error: str

class Push(TypedDict):
    kind: Literal["Push"]
    n: int

class Pop(TypedDict):
    kind: Literal["Pop"]

class Add(TypedDict):
    kind: Literal["Add"]

class Sub(TypedDict):
    kind: Literal["Sub"]

class Mul(TypedDict):
    kind: Literal["Mul"]

class Dup(TypedDict):
    kind: Literal["Dup"]

class Swap(TypedDict):
    kind: Literal["Swap"]

class Jz(TypedDict):
    kind: Literal["Jz"]
    target: int

class Jmp(TypedDict):
    kind: Literal["Jmp"]
    target: int

class Print(TypedDict):
    kind: Literal["Print"]

class Halt(TypedDict):
    kind: Literal["Halt"]

Instr = Push | Pop | Add | Sub | Mul | Dup | Swap | Jz | Jmp | Print | Halt

def stack_vm(prog: list[Instr]) -> Ok[list[int]] | Err:
    stack: list[int] = []
    output: list[int] = []
    ip: int = 0
    steps: int = 0
    max_steps: int = 1000

    while ip < len(prog):
        if steps >= max_steps:
            return Err({"ok": False, "error": "step limit exceeded"})
        steps += 1

        instr = prog[ip]
        match instr:
            case Push(n):
                stack.append(n)
            case Pop():
                if not stack:
                    return Err({"ok": False, "error": f"stack underflow at {ip}"})
                stack.pop()
            case Add():
                if len(stack) < 2:
                    return Err({"ok": False, "error": f"stack underflow at {ip}"})
                b = stack.pop()
                a = stack.pop()
                stack.append(a + b)
            case Sub():
                if len(stack) < 2:
                    return Err({"ok": False, "error": f"stack underflow at {ip}"})
                b = stack.pop()
                a = stack.pop()
                stack.append(a - b)
            case Mul():
                if len(stack) < 2:
                    return Err({"ok": False, "error": f"stack underflow at {ip}"})
                b = stack.pop()
                a = stack.pop()
                stack.append(a * b)
            case Dup():
                if not stack:
                    return Err({"ok": False, "error": f"stack underflow at {ip}"})
                stack.append(stack[-1])
            case Swap():
                if len(stack) < 2:
                    return Err({"ok": False, "error": f"stack underflow at {ip}"})
                stack[-1], stack[-2] = stack[-2], stack[-1]
            case Jz(target):
                if not stack:
                    return Err({"ok": False, "error": f"stack underflow at {ip}"})
                if stack.pop() == 0:
                    ip = target
                    continue
            case Jmp(target):
                if target < 0 or target >= len(prog):
                    return Err({"ok": False, "error": f"bad jump at {ip}"})
                ip = target
                continue
            case Print():
                if not stack:
                    return Err({"ok": False, "error": f"stack underflow at {ip}"})
                output.append(stack.pop())
            case Halt():
                break
        ip += 1

    return Ok({"ok": True, "value": output})

