export function competition_rank(players: Player[]): ([number, string])[] {
    const sortedPlayers = players.sort((a, b) => b.score - a.score || a.name.localeCompare(b.name));
    const ranks = sortedPlayers.map((player, index) => {
        if (index === 0 || player.score !== sortedPlayers[index - 1].score) {
            return [index + 1, player.name];
        } else {
            return [ranks[index - 1][0], player.name];
        }
    });
    return ranks;
}

