    const m = a.length, n = b.length;
    const dp = Array.from({ length: m + 1 }, () => Array(n + 1).fill(0));

    for (let i = 1; i <= m; i++) {
        dp[i][0] = i;
    }

    for (let j = 1; j <= n; j++) {
        dp[0][j] = j;
    }

    for (let i = 1; i <= m; i++) {
        for (let j = 1; j <= n; j++) {
            dp[i][j] = Math.min(
                dp[i - 1][j] + 1,      // Delete
                dp[i][j - 1] + 1,      // Insert
                dp[i - 1][j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1) // Replace
            );
            if (i > 1 && j > 1 && a[i - 1] === b[j - 2] && a[i - 2] === b[j - 1]) {
                dp[i][j] = Math.min(dp[i][j], dp[i - 2][j - 2] + 1); // Swap
            }
        }
    }

    return dp[m][n];
}

