export function heading_numbers(lines: string[]): string[] {
    let counters: { [key: number]: number } = { 1: 0, 2: 0, 3: 0 };
    return lines
        .filter(line => /^#{1,3} .+$/.test(line))
        .map(line => {
            const level = line.match(/^#+/)?.[0].length || 0;
            const title = line.slice(level + 1).trim();
            counters[level]++;
            for (let i = level + 1; i <= 3; i++) counters[i] = 0;
            return `${Object.values(counters).join('.')} ${title}`;
        });
}

