function k_most_frequent(xs: number[], k: number): [number, number][] {
  const countMap = new Map<number, number>();
  xs.forEach(x => countMap.set(x, (countMap.get(x) || 0) + 1));
  const sortedCounts = Array.from(countMap.entries()).sort((a, b) => {
    if (b[1] === a[1]) return a[0] - b[0];
    return b[1] - a[1];
  });
  return sortedCounts.slice(0, k);
}

