type Result<T> = { ok: true; value: T } | { ok: false; error: string };

function flatten_nested(s: string): Result<[number[], number]> {
    s = s.replace(/\s/g, '');
    const result: number[] = [];
    let depth = 0, maxDepth = 0;

    function parseElement(index: number): number {
        if (s[index] === '[') {
            depth++;
            maxDepth = Math.max(maxDepth, depth);
            const end = findMatchingBracket(index);
            if (end === -1) return -1;
            const subResult = parseNestedList(end + 1);
            if (subResult === -1) return -1;
            result.push(...subResult);
            depth--;
            return end;
        } else if (s[index] === '-') {
            const num = parseNumber(index + 1);
            if (num === -1) return -1;
            result.push(num);
            return index + num.toString().length;
        } else {
            const num = parseNumber(index);
            if (num === -1) return -1;
            result.push(num);
            return index + num.toString().length;
        }
    }

    function parseNestedList(start: number): number[] | -1 {
        if (s[start] !== '[') return -1;
        let index = start + 1;
        while (index < s.length) {
            if (s[index] === ']') return index;
            if (s[index] === ',') {
                index++;
                continue;
            }
            const endIndex = parseElement(index);
            if (endIndex === -1) return -1;
            index = endIndex + 1;
        }
        return -1;
    }

    function parseNumber(start: number): number | -1 {
        if (start >= s.length || !/[-+]?\d/.test(s[start])) return -1;
        let index = start;
        while (index < s.length && /\d/.test(s[index])) index++;
        return parseInt(s.substring(start, index), 10);
    }

    function findMatchingBracket(start: number): number {
        let count = 1;
        for (let i = start + 1; i < s.length; i++) {
            if (s[i] === '[') count++;
            else if (s[i] === ']') count--;
            if (count === 0) return i;
        }
        return -1;
    }

    const endIndex = parseNestedList(0);
    if (endIndex === -1 || endIndex !== s.length - 1) {
        return { ok: false, error: `invalid at ${endIndex}` };
    }

    return { ok: true, value: [result, maxDepth] };
}

