function max_subarray(xs: number[]): [number, number, number] | null {
    if (xs.length === 0) return null;

    let maxSum = -Infinity;
    let start = 0;
    let end = 0;
    let tempStart = 0;
    let currentSum = 0;

    for (let i = 0; i < xs.length; i++) {
        currentSum += xs[i];
        if (currentSum > maxSum) {
            maxSum = currentSum;
            start = tempStart;
            end = i;
        }
        if (currentSum < 0) {
            currentSum = 0;
            tempStart = i + 1;
        }
    }

    return [maxSum, start, end];
}

