type OrderEvent =
  | { kind: "Create"; id: string }
  | { kind: "Pay"; id: string }
  | { kind: "Ship"; id: string }
  | { kind: "Cancel"; id: string };
type Result<T> = { ok: true; value: T } | { ok: false; error: string };

function order_states(events: OrderEvent[]): Result<([string, string])[]> {
  const orders: { [id: string]: string } = {};

  for (const event of events) {
    switch (event.kind) {
      case "Create":
        if (orders[event.id]) {
          return { ok: false, error: `duplicate order: ${event.id}` };
        }
        orders[event.id] = "created";
        break;
      case "Pay":
        if (!orders[event.id]) {
          return { ok: false, error: `unknown order: ${event.id}` };
        }
        if (orders[event.id] !== "created") {
          return { ok: false, error: `cannot pay ${event.id} from ${orders[event.id]}` };
        }
        orders[event.id] = "paid";
        break;
      case "Ship":
        if (!orders[event.id]) {
          return { ok: false, error: `unknown order: ${event.id}` };
        }
        if (orders[event.id] !== "paid") {
          return { ok: false, error: `cannot ship ${event.id} from ${orders[event.id]}` };
        }
        orders[event.id] = "shipped";
        break;
      case "Cancel":
        if (!orders[event.id]) {
          return { ok: false, error: `unknown order: ${event.id}` };
        }
        if (orders[event.id] !== "created" && orders[event.id] !== "paid") {
          return { ok: false, error: `cannot cancel ${event.id} from ${orders[event.id]}` };
        }
        orders[event.id] = "cancelled";
        break;
    }
  }

  const result: [string, string][] = Object.entries(orders).sort((a, b) => a[0].localeCompare(b[0]));
  return { ok: true, value: result };
}

