export function parse_csv_line(s: string): Result<string[]> {
    const result: string[] = [];
    let i = 0;
    while (i < s.length) {
        if (s[i] === '"') {
            i++; // Skip the opening quote
            let value = '';
            while (i < s.length && s[i] !== '"') {
                if (s[i] === '\\') {
                    i++; // Skip the backslash
                    if (i < s.length) {
                        value += s[i];
                    } else {
                        return { ok: false, error: 'unterminated quote' };
                    }
                } else {
                    value += s[i];
                }
                i++;
            }
            if (i === s.length) {
                return { ok: false, error: 'unterminated quote' };
            }
            i++; // Skip the closing quote
            result.push(value);
        } else {
            let value = '';
            while (i < s.length && s[i] !== ',') {
                value += s[i];
                i++;
            }
            result.push(value);
        }
        if (i < s.length && s[i] === ',') {
            i++; // Skip the comma
        }
    }
    return { ok: true, value: result };
}

