type ParseResult = { kind: 'value', value: number } | { kind: 'error', error: string };

function parse_expr(s: string, pos: number): ParseResult {
    const termResult = parse_term(s, pos);
    if (termResult.kind === 'error') {
        return termResult;
    }
    let value = termResult.value;
    let newPos = termResult.pos;
    while (newPos < s.length) {
        const op = s[newPos];
        if (op !== '+' && op !== '-') {
            break;
        }
        newPos++;
        const nextTermResult = parse_term(s, newPos);
        if (nextTermResult.kind === 'error') {
            return nextTermResult;
        }
        if (op === '+') {
            value += nextTermResult.value;
        } else {
            value -= nextTermResult.value;
        }
        newPos = nextTermResult.pos;
    }
    return { kind: 'value', value };
}

function parse_term(s: string, pos: number): ParseResult {
    const factorResult = parse_factor(s, pos);
    if (factorResult.kind === 'error') {
        return factorResult;
    }
    let value = factorResult.value;
    let newPos = factorResult.pos;
    while (newPos < s.length) {
        const op = s[newPos];
        if (op !== '*' && op !== '/') {
            break;
        }
        newPos++;
        const nextFactorResult = parse_factor(s, newPos);
        if (nextFactorResult.kind === 'error') {
            return nextFactorResult;
        }
        if (op === '*') {
            value *= nextFactorResult.value;
        } else {
            if (nextFactorResult.value === 0) {
                return { kind: 'error', error: 'division by zero' };
            }
            value = Math.trunc(value / nextFactorResult.value);
        }
        newPos = nextFactorResult.pos;
    }
    return { kind: 'value', value };
}

function parse_factor(s: string, pos: number): ParseResult {
    if (pos >= s.length) {
        return { kind: 'error', error: 'unexpected end' };
    }
    if (s[pos] === '(') {
        pos++;
        const exprResult = parse_expr(s, pos);
        if (exprResult.kind === 'error') {
            return exprResult;
        }
        if (pos >= s.length || s[pos] !== ')') {
            return { kind: 'error', error: 'unexpected end' };
        }
        pos++;
        return exprResult;
    }
    if (s[pos] >= '0' && s[pos] <= '9') {
        let num = 0;
        while (pos < s.length && s[pos] >= '0' && s[pos] <= '9') {
            num = num * 10 + (s[pos] - '0');
            pos++;
        }
        return { kind: 'value', value: num, pos };
    }
    return { kind: 'error', error: `unexpected character: ${s[pos]}` };
}

