type Result<T> = { ok: true; value: T } | { ok: false; error: string };

function rle_decode(s: string): Result<string> {
    let result = '';
    let i = 0;

    while (i < s.length) {
        const char = s[i];
        i++;

        if (char >= '0' && char <= '9') {
            return { ok: false, error: 'missing character before count' };
        }

        let count = '';
        while (i < s.length && s[i] >= '0' && s[i] <= '9') {
            count += s[i];
            i++;
        }

        if (count.startsWith('0')) {
            return { ok: false, error: `bad count for ${char}` };
        }

        const repeatCount = count ? parseInt(count, 10) : 1;
        result += char.repeat(repeatCount);
    }

    return { ok: true, value: result };
}

