type Cmd = { kind: "Forward"; steps: number } | { kind: "TurnLeft" } | { kind: "TurnRight" };

function robot_walk(cmds: Cmd[], obstacles: ([number, number])[]): [number, number, string] {
    let x = 0, y = 0, direction = "N";
    for (const cmd of cmds) {
        switch (cmd.kind) {
            case "Forward":
                for (let i = 0; i < cmd.steps; i++) {
                    const [dx, dy] = directionToDelta(direction);
                    const nextX = x + dx, nextY = y + dy;
                    if (!obstacles.some(([ox, oy]) => ox === nextX && oy === nextY)) {
                        x = nextX;
                        y = nextY;
                    } else {
                        break;
                    }
                }
                break;
            case "TurnLeft":
                direction = turnLeft(direction);
                break;
            case "TurnRight":
                direction = turnRight(direction);
                break;
        }
    }
    return [x, y, direction];
}

function directionToDelta(direction: string): [number, number] {
    switch (direction) {
        case "N": return [0, 1];
        case "E": return [1, 0];
        case "S": return [0, -1];
        case "W": return [-1, 0];
        default: throw new Error("Invalid direction");
    }
}

function turnLeft(direction: string): string {
    switch (direction) {
        case "N": return "W";
        case "E": return "N";
        case "S": return "E";
        case "W": return "S";
        default: throw new Error("Invalid direction");
    }
}

function turnRight(direction: string): string {
    switch (direction) {
        case "N": return "E";
        case "E": return "S";
        case "S": return "W";
        case "W": return "N";
        default: throw new Error("Invalid direction");
    }
}

