type Result<T> = { ok: true; value: T } | { ok: false; error: string };

function roman_to_int(s: string): Result<number> {
    if (s === "") return { ok: false, error: "empty" };

    const romanMap: { [key: string]: number } = {
        I: 1, V: 5, X: 10, L: 50, C: 100, D: 500, M: 1000,
        IV: 4, IX: 9, XL: 40, XC: 90, CD: 400, CM: 900
    };

    let result = 0;
    let i = 0;

    while (i < s.length) {
        if (romanMap[s.substring(i, i + 2)]) {
            result += romanMap[s.substring(i, i + 2)];
            i += 2;
        } else if (romanMap[s[i]]) {
            result += romanMap[s[i]];
            i += 1;
        } else {
            return { ok: false, error: `invalid character: ${s[i]}` };
        }
    }

    if (result < 1 || result > 3999) return { ok: false, error: "not canonical" };

    return { ok: true, value: result };
}

