export function spiral_order(m: number[][]): number[] {
    if (m.length === 0 || m[0].length === 0) return [];

    let result: number[] = [];
    let top = 0, bottom = m.length - 1, left = 0, right = m[0].length - 1;

    while (top <= bottom && left <= right) {
        // Traverse from left to right along the top row
        for (let i = left; i <= right; i++) result.push(m[top][i]);
        top++;

        // Traverse from top to bottom along the right column
        for (let i = top; i <= bottom; i++) result.push(m[i][right]);
        right--;

        // Traverse from right to left along the bottom row, if still within bounds
        if (top <= bottom) {
            for (let i = right; i >= left; i--) result.push(m[bottom][i]);
            bottom--;
        }

        // Traverse from bottom to top along the left column, if still within bounds
        if (left <= right) {
            for (let i = bottom; i >= top; i--) result.push(m[i][left]);
            left++;
        }
    }

    return result;
}

