function tic_tac_toe(board: string[]): string {
    const rows = board;
    const cols = board.map(row => row[0] + row[1] + row[2]);
    const diags = [board[0][0] + board[1][1] + board[2][2], board[0][2] + board[1][1] + board[2][0]];
    const allLines = [...rows, ...cols, ...diags];

    const countMarks = (mark: string) => allLines.filter(line => line === mark.repeat(3)).length;
    const xCount = countMarks("X");
    const oCount = countMarks("O");

    if (xCount !== oCount && xCount !== oCount + 1) return "invalid";
    if (xCount > oCount) return "invalid";
    if (xCount === oCount && xCount > 0) return "invalid";

    if (xCount === 1 && oCount === 0) return "invalid";
    if (oCount === 1 && xCount === 0) return "invalid";

    if (xCount === 1 && oCount === 0) return "X wins";
    if (oCount === 1 && xCount === 0) return "O wins";

    if (xCount === 2 && oCount === 1) return "X wins";
    if (oCount === 2 && xCount === 1) return "O wins";

    if (board.every(row => row.includes("."))) return "in progress";

    return "draw";
}

