type Session = { user: string; kind: string; time: number };

function session_totals(events: Session[]): ([string, number])[] {
    const userSessions: { [key: string]: { start: number | null; total: number } } = {};

    events.forEach(event => {
        if (event.kind === "login") {
            if (userSessions[event.user].start === null) {
                userSessions[event.user].start = event.time;
            }
        } else if (event.kind === "logout") {
            if (userSessions[event.user].start !== null) {
                userSessions[event.user].total += event.time - userSessions[event.user].start;
                userSessions[event.user].start = null;
            }
        }
    });

    // Close any open sessions at the end
    for (const user in userSessions) {
        if (userSessions[user].start !== null) {
            userSessions[user].total += events[events.length - 1].time - userSessions[user].start;
        }
    }

    // Convert the result to the required format
    return Object.entries(userSessions).map(([user, { total }]) => [user, total]);
}

