function stack_vm(prog: Instr[]): Result<number[]> {
  const stack: number[] = [];
  const output: number[] = [];
  let pc = 0;
  let steps = 0;

  while (pc < prog.length && steps < 1000) {
    const instr = prog[pc];
    steps++;

    switch (instr.kind) {
      case "Push":
        stack.push(instr.n);
        break;
      case "Pop":
        if (stack.length === 0) return { ok: false, error: `stack underflow at ${pc}` };
        stack.pop();
        break;
      case "Add":
        if (stack.length < 2) return { ok: false, error: `stack underflow at ${pc}` };
        stack.push(stack.pop()! + stack.pop()!);
        break;
      case "Sub":
        if (stack.length < 2) return { ok: false, error: `stack underflow at ${pc}` };
        const b = stack.pop()!;
        const a = stack.pop()!;
        stack.push(a - b);
        break;
      case "Mul":
        if (stack.length < 2) return { ok: false, error: `stack underflow at ${pc}` };
        stack.push(stack.pop()! * stack.pop()!);
        break;
      case "Dup":
        if (stack.length === 0) return { ok: false, error: `stack underflow at ${pc}` };
        stack.push(stack[stack.length - 1]);
        break;
      case "Swap":
        if (stack.length < 2) return { ok: false, error: `stack underflow at ${pc}` };
        const temp = stack.pop()!;
        stack.pop();
        stack.push(temp);
        stack.push(stack.pop()!);
        break;
      case "Jz":
        if (stack.length === 0) return { ok: false, error: `stack underflow at ${pc}` };
        if (stack.pop()! === 0) pc = instr.target;
        break;
      case "Jmp":
        pc = instr.target;
        break;
      case "Print":
        if (stack.length === 0) return { ok: false, error: `stack underflow at ${pc}` };
        output.push(stack.pop()!);
        break;
      case "Halt":
        return { ok: true, value: output };
    }
  }

  return { ok: false, error: "step limit exceeded" };
}

