function poker_hand(cards: string[]): string {
    const ranks = "23456789TJQKA";
    const suits = "CDHS";
    const rankValues = new Map([...ranks].map((r, i) => [r, i]));
    const suitCounts = new Map(suits.split('').map(s => [s, 0]));
    const rankCounts = new Map([...ranks].map(r => [r, 0]));

    // Validate and count cards
    for (const card of cards) {
        if (card.length !== 2 || !ranks.includes(card[0]) || !suits.includes(card[1])) return "invalid";
        suitCounts.set(card[1], (suitCounts.get(card[1]) || 0) + 1);
        rankCounts.set(card[0], (rankCounts.get(card[0]) || 0) + 1);
    }

    // Check for repeated cards
    for (const count of rankCounts.values()) {
        if (count > 1) return "invalid";
    }

    // Check for straight flush
    if (suitCounts.size === 1 && isStraight(cards.map(card => rankValues.get(card[0])))) return "straight flush";

    // Check for four of a kind
    if (rankCounts.has(4)) return "four of a kind";

    // Check for full house
    if (rankCounts.has(3) && rankCounts.has(2)) return "full house";

    // Check for flush
    if (suitCounts.size === 1) return "flush";

    // Check for straight
    if (isStraight(cards.map(card => rankValues.get(card[0])))) return "straight";

    // Check for three of a kind
    if (rankCounts.has(3)) return "three of a kind";

    // Check for two pair
    if (Array.from(rankCounts.values()).filter(count => count === 2).length === 2) return "two pair";

    // Check for one pair
    if (rankCounts.has(2)) return "one pair";

    // High card
    return "high card";
}

function isStraight(ranks: number[]): boolean {
    ranks.sort((a, b) => a - b);
    for (let i = 0; i < ranks.length - 1; i++) {
        if (ranks[i] + 1 !== ranks[i + 1]) return false;
    }
    return true;
}

