function tokenize(s: string): Result<Token[]> {
  const tokens: Token[] = [];
  let i = 0;

  while (i < s.length) {
    if (s[i] === ' ') {
      i++;
      continue;
    }

    if (s[i] >= '0' && s[i] <= '9') {
      let num = 0;
      while (i < s.length && s[i] >= '0' && s[i] <= '9') {
        num = num * 10 + (s[i] - '0');
        i++;
      }
      tokens.push({ kind: "Num", value: num });
      continue;
    }

    if (s[i] >= 'a' && s[i] <= 'z' || s[i] === '_') {
      let name = s[i];
      i++;
      while (i < s.length && (s[i] >= 'a' && s[i] <= 'z' || s[i] >= '0' && s[i] <= '9' || s[i] === '_')) {
        name += s[i];
        i++;
      }
      tokens.push({ kind: "Ident", name });
      continue;
    }

    const twoCharSymbols = ["==", "<=", ">=", "!="];
    const oneCharSymbols = ["+", "-", "*", "/", "=", "<", ">", "(", ")", ","];

    for (const sym of twoCharSymbols) {
      if (s.startsWith(sym, i)) {
        tokens.push({ kind: "Sym", text: sym });
        i += sym.length;
        continue;
      }
    }

    for (const sym of oneCharSymbols) {
      if (s[i] === sym) {
        tokens.push({ kind: "Sym", text: sym });
        i++;
        continue;
      }
    }

    return { ok: false, error: `unexpected character: ${s[i]} at ${i}` };
  }

  return { ok: true, value: tokens };
}

